"use strict";(self.webpackChunkkymira=self.webpackChunkkymira||[]).push([[8802],{3806:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>a,toc:()=>h});var a=n(61373),o=n(74848),i=n(28453);const s={title:"Conferences in 2025",description:"Some summaries, links, and thoughts on conferences we attended to in 2025.",slug:"conferences-2025",authors:["kylie"],tags:["studio wtchcrft","video games"],image:"/img/dervin-sense-making.png"},r=void 0,l={authorsImageUrls:[void 0]},h=[{value:"Narrascope",id:"narrascope",level:2},{value:"Finding the Pixel: Information Seeking Behaviors Towards Holistic Narrative Design",id:"finding-the-pixel-information-seeking-behaviors-towards-holistic-narrative-design",level:3},{value:"Crafting Kissable Characters (Whether Your Game has Romance in It or Not!)",id:"crafting-kissable-characters-whether-your-game-has-romance-in-it-or-not",level:3},{value:"Mathematically Proving Your Stories Have No Bugs",id:"mathematically-proving-your-stories-have-no-bugs",level:3},{value:"QGCon",id:"qgcon",level:2},{value:"ThinkyCon",id:"thinkycon",level:2},{value:"Is a Puzzle Game Without An Undo Still A Puzzle Game? - JohnLee Cooper",id:"is-a-puzzle-game-without-an-undo-still-a-puzzle-game---johnlee-cooper",level:3},{value:"Using a puzzle solver to aid design, discovery, QA, and playtesting \u2013 Jagriff",id:"using-a-puzzle-solver-to-aid-design-discovery-qa-and-playtesting--jagriff",level:3},{value:"Art of Nurikabe World - Wiebke Spieker",id:"art-of-nurikabe-world---wiebke-spieker",level:3},{value:"Composing Music for Chants Of Sennaar - Thomas Brunet",id:"composing-music-for-chants-of-sennaar---thomas-brunet",level:3},{value:"Testing Blue Prince - Tonda Ros",id:"testing-blue-prince---tonda-ros",level:3},{value:"Conclusion",id:"conclusion",level:2}];function d(e){const t={a:"a",h2:"h2",h3:"h3",img:"img",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"The end of the year is approaching which means it\u2019s time for annual re-cap and review posts! First up is conference talks. We attended 3 of them this year, which probably resulted in listening to around 50 talks. It was a lot of information to take in."}),"\n",(0,o.jsx)(t.p,{children:"This blog post is going to be biased towards ThinkyCon as it was the most recent conference and likely the one that had the largest influence on Fatemender design decisions so far. The rest are going to be the few talks that were able to stick with me across multiple months."}),"\n",(0,o.jsx)(t.h2,{id:"narrascope",children:"Narrascope"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.a,{href:"https://narrascope.org/",children:"NarraScope"})," is an annual conference put on by the ",(0,o.jsx)(t.a,{href:"https://www.iftechfoundation.org/",children:"Interactive Fiction Technology Foundation"}),". It\u2019s been on my radar for years because of it\u2019s focus on interactive narratives and story telling in games. It\u2019s a hybrid event with talks being given in person and streamed online at the same time."]}),"\n",(0,o.jsx)(t.p,{children:"We attended online and watched the streams continuously during the live sessions. This however turned out to be very painful. The in-person setups weren\u2019t great for the online audience. We had some talks we wanted to attend but due to the audio issues in the live streams we ended up jumping around between sessions and just watching whichever one had the best audio quality as some were near impossible to listen too."}),"\n",(0,o.jsx)(t.p,{children:"But that doesn\u2019t mean we didn\u2019t get some good takeaways from the event. There were a few talks that definitely stuck with us."}),"\n",(0,o.jsx)(t.h3,{id:"finding-the-pixel-information-seeking-behaviors-towards-holistic-narrative-design",children:"Finding the Pixel: Information Seeking Behaviors Towards Holistic Narrative Design"}),"\n",(0,o.jsx)(t.p,{children:"This talk title peaked my interest due to my background in information studies. Information seeking behaviours is a big topic in the library studies world. My education and my passion hobby overlapping? What a find!"}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/AekYBb576sU?si=65KbdXUixgBw4kwM",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:"It was a treat to hear the language from my degree being used to talk about user behaviours in games. It was honestly a connection I never thought of making but it feels so obvious now. That the different ways people seek information influences how they would seek information in a game. The talk also featured some of my favourite graphs from library school, but didn\u2019t include my absolute favourite, Brenda Dervin\u2019s sense-making model:"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.img,{src:n(40537).A+"",width:"660",height:"523"}),"\n(I made a lot of fun of this graphic while I was in library school and am now very fond of it.)"]}),"\n",(0,o.jsx)(t.h3,{id:"crafting-kissable-characters-whether-your-game-has-romance-in-it-or-not",children:"Crafting Kissable Characters (Whether Your Game has Romance in It or Not!)"}),"\n",(0,o.jsx)(t.p,{children:"With our first game being made for a romance themed game jam, romance in games was still a key concept to us back in May. It will probably be an evergreen topic but it\u2019s not central to our current game."}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/nrEaXtcJReI?si=0aQ2j5ovS-dzwpOP",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:"The big thing I took away from this talk was the importance of having lovable characters and having a range of different characters to appeal to more people. All characters should have appeal."}),"\n",(0,o.jsx)(t.h3,{id:"mathematically-proving-your-stories-have-no-bugs",children:"Mathematically Proving Your Stories Have No Bugs"}),"\n",(0,o.jsx)(t.p,{children:"I\u2019ve been following different dialog tools for a few years now and Yarn Spinner has always seemed cool to me. The idea of mathematically testing your branching stories also seems cool to me. Having just come off of making 2 narrative games it was really interesting to see a tool and approach for testing branching."}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/CcwBAXvOevs?si=DBy2EzamaGwImVaR",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:"Given the size of the games we\u2019ve made and the small size of our teams testing like this doesn\u2019t seem as necessary as we had a low enough number of scenes that we could test them all ourselves and make sure things trigger or don\u2019t trigger when needed. But it\u2019s cool to have ideas like this floating around in my brain for more ambitious projects in the future."}),"\n",(0,o.jsxs)(t.p,{children:["The con talks are hosted on the ",(0,o.jsx)(t.a,{href:"https://www.youtube.com/@IFTechFoundation",children:"IFTechFoundation YouTube channel"}),". They have years of talks available there right now, going back to 2020."]}),"\n",(0,o.jsx)(t.h2,{id:"qgcon",children:"QGCon"}),"\n",(0,o.jsxs)(t.p,{children:["The ",(0,o.jsx)(t.a,{href:"https://www.qgcon.org/",children:"Queerness in Games Conference"})," was held at the BANQ in Montreal, a mere 20 minute walk from our apartment. We attended as Arcade Presenters, showing Love in the Time of Spellphage. I already blogged about our time there so I won\u2019t go into what it was like to be there."]}),"\n",(0,o.jsx)(t.p,{children:"In the mornings before we went to our table we were able to catch a few talks and we\u2019ve been told that the talks would be put online to watch later. However none of the talks for QGCon have made it online yet so I\u2019ll try to remember to update this blog post when they do."}),"\n",(0,o.jsx)(t.h2,{id:"thinkycon",children:"ThinkyCon"}),"\n",(0,o.jsxs)(t.p,{children:["ThinkCon is a yearly conference put on by the folks behind ",(0,o.jsx)(t.a,{href:"https://thinkygames.com/",children:"Thinky Games"}),". I only learned of the Thinky Games community this year while doing research for Fatemender and only heard of the conference about 3 weeks before it happened. It was both free and online so the last minute discovery wasn\u2019t a downside as it made it easy to attend. However in the end my wife did describe the conference as \u201cthe most expensive conference we\u2019ve attended\u201d due to all the ideas it added to the Fatemender backlog that would require serious dev time."]}),"\n",(0,o.jsx)(t.p,{children:"There were excellent takeaways from the ThinkyCon talks that led to some major changes in our game."}),"\n",(0,o.jsx)(t.h3,{id:"is-a-puzzle-game-without-an-undo-still-a-puzzle-game---johnlee-cooper",children:"Is a Puzzle Game Without An Undo Still A Puzzle Game? - JohnLee Cooper"}),"\n",(0,o.jsx)(t.p,{children:"We\u2019ve been testing Fatemender with players for almost 2 months now. We\u2019ve heard that people find the game difficult and that there were ways to make a very punishing mistakes. We put more time into onboarding, ramping of difficulty over time and also adding guardrails so folks would make fewer misplays. But the question remained, would an undo button ruin it? In comes a talk about undo."}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/Pkcp_IASsIc?si=BTm26Dv3yzKNmDzc",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:"Multiple talks at the conference did bring up the undo button but this was the first talk that really focused on it. We\u2019d been debating it for a while already and the conference forced it into the spotlight. One of the big debate points was, is our game really a puzzle game? And do all puzzle games have undo?\nWe already know that puzzle games aren\u2019t big sellers so there's a hesitation to lean fully into puzzle genre expectations. And since most of our levels have an element of RNG generation we also don\u2019t promise solvability. Which feels like it disqualifies us from being a puzzle game... So does that disqualify the expectation of undo?"}),"\n",(0,o.jsx)(t.p,{children:"But the talks went on and my wife started to look into the technical side of implementing undo. The Thinky Games crowd feels like the audience that would like our game so it made sense to try to at least hue to some puzzle genre expectations."}),"\n",(0,o.jsx)(t.p,{children:"3 days after the conference we launched the undo button."}),"\n",(0,o.jsx)(t.h3,{id:"using-a-puzzle-solver-to-aid-design-discovery-qa-and-playtesting--jagriff",children:"Using a puzzle solver to aid design, discovery, QA, and playtesting \u2013 Jagriff"}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/nBBbpU7Xxlw?si=I5-nrQycbH_9sC-q",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:"We didn\u2019t end up writing a solver but it was a conversation in the house for a few days thanks to this talk. It was also just really interesting hearing about Jagriff\u2019s workflow with his solver for both level design and testing. Currently a solver feels like a huge lift for Fatemender and we already have some self given deadlines we want to hit but it will probably often be at the back of our minds."}),"\n",(0,o.jsx)(t.h3,{id:"art-of-nurikabe-world---wiebke-spieker",children:"Art of Nurikabe World - Wiebke Spieker"}),"\n",(0,o.jsx)(t.p,{children:"The unassuming last talk of day 1 about approaching visuals in a puzzle game ended up holding one of the most important suggestions for us. Solving one of our own problems; how to stop all your screenshots from looking the same when your game is a grid."}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/z0YuRPRyqso?si=dZM8nCVF09tmk_49",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:"This came in just in the last few minutes of the talk, the suggestion of changing up the shape of your grid levels. So far all the levels in Fatemender were 3x4, while each new map is a new experience it\u2019s hard to convey that with the screenshots alone. So what if you have a grid with a hole in the middle? Maybe an L shape? Stay tuned for future Fatemender updates to see how this influenced the game."}),"\n",(0,o.jsx)(t.h3,{id:"composing-music-for-chants-of-sennaar---thomas-brunet",children:"Composing Music for Chants Of Sennaar - Thomas Brunet"}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/wl-MphoMIz4?si=tj9bsu-8OKAQImAI",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:"I wasn\u2019t sure what to expect about a talk on music at a puzzle conference but this was a nice shakeup to the design and process talks. And it ended up being really interesting to hear about the role of music in puzzle games. So far we\u2019ve been approaching Fatemender with the main idea of not wanting the music to be distracting from the problem solving. It\u2019s not meant to steal the scene. Brunet does bring this up and showed how they even have plenty of space for silence in Chants of Sennaar. But one of the best lines, maybe from the whole conference was \u201cthe music knows more than you\u201d. Meaning that you as the player don\u2019t have all the information of the world or puzzle but the music does and it should be conveying that information in a way that might not yet be clear to the player."}),"\n",(0,o.jsx)(t.h3,{id:"testing-blue-prince---tonda-ros",children:"Testing Blue Prince - Tonda Ros"}),"\n",(0,o.jsx)(t.p,{children:"I\u2019ll admit, seeing Tonda Ros on the schedule before the conference started was a huge influence in wanting to attend the conference. Blue Prince is my top game of the year and it felt like such a treat to hear anything about it's creation. This is the first talk Ros has given since the release of the game. Blue Prince was the first game he made. How could he give a talk without spoiling the game? Well he does, he doesn\u2019t spoil a single thing, there was maybe even just one screenshot. So if you\u2019re interested in his process for finding playtesters but don\u2019t want to have Blue Prince spoiled in anyway you can still watch this talk."}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/z08rqlKkssg?si=yP_SHH57DFg77Ate",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:"Ros\u2019s approach to ask streamers to be playtesters feels genius and seems to have been really successful for him. He didn't want players to feel watched, he didn't want folks to be motivated by money, or fill our surveys. Just pure gameplay and reactions. This has definitely inspired us to try to take a similar approach to finding some early Fatemender playtesters as soon as we have our demo solidified."}),"\n",(0,o.jsxs)(t.p,{children:["All talks from this conference and previous ThinkyCons are ",(0,o.jsx)(t.a,{href:"https://www.youtube.com/@thinkygames",children:"available on YouTube"}),"."]}),"\n",(0,o.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,o.jsx)(t.p,{children:"This as been our first year as a studio. We hadn\u2019t really planned on attending any of these events until a few weeks before (aside from QGCon) so it was cool to be able to fully devote multiple days to just watching talks and learning new things. But also boy it\u2019s time consuming and mentally difficult. For Narrascope it was a heat wave weekend and we spent the whole time basically trapped in our bedroom, which we set up to be a temporary office space because it\u2019s our only room with air conditioning. I found it hard to stay focused through hours of information while also not being super comfortable. The idea of attending in person seems cool but have no plans on going to the US any time soon."}),"\n",(0,o.jsx)(t.p,{children:"Still very grateful that so many conferences are online these days as we probably wouldn't have attended them otherwise. Narrascope struggled with managing audio but we were still able to catch of lot of talks. ThinkyCon was almost flawless on it's tech side which felt like magic. I'm already excited to see what the programming for next years events looks like."}),"\n",(0,o.jsx)(t.p,{children:"Blog activity is about to take off over the next few weeks. I\u2019ve got a year of reviews for books and games to write up. Maybe a timeline of studio development. An art year in review as well. It was a big year so I expect some big posts."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},40537:(e,t,n)=>{n.d(t,{A:()=>a});const a=n.p+"assets/images/dervin-sense-making-ba7c9855b7b33e677ed1a9689f3bf4aa.png"},28453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var a=n(96540);const o={},i=a.createContext(o);function s(e){const t=a.useContext(i);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(i.Provider,{value:t},e.children)}},61373:e=>{e.exports=JSON.parse('{"permalink":"/blog/conferences-2025","source":"@site/blog/2025-11-25-conferences-2025.md","title":"Conferences in 2025","description":"Some summaries, links, and thoughts on conferences we attended to in 2025.","date":"2025-11-25T00:00:00.000Z","tags":[{"inline":true,"label":"studio wtchcrft","permalink":"/blog/tags/studio-wtchcrft"},{"inline":true,"label":"video games","permalink":"/blog/tags/video-games"}],"readingTime":10.36,"hasTruncateMarker":false,"authors":[{"name":"Kylie","title":"Admin","url":"https://github.com/kylies","imageURL":"https://github.com/kylies.png","key":"kylie","page":null}],"frontMatter":{"title":"Conferences in 2025","description":"Some summaries, links, and thoughts on conferences we attended to in 2025.","slug":"conferences-2025","authors":["kylie"],"tags":["studio wtchcrft","video games"],"image":"/img/dervin-sense-making.png"},"unlisted":false,"prevItem":{"title":"Making Steam capsule art","permalink":"/blog/fatemender-capsule"},"nextItem":{"title":"End of summer studio activities","permalink":"/blog/summer-2025"}}')}}]);